CREATE OR REPLACE FUNCTION pg_temp.team_check(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',message; END IF; END $$;
CREATE OR REPLACE FUNCTION pg_temp.team_reject(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN EXECUTE statement;RAISE EXCEPTION 'Unexpected success: %',statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE; END IF; END $$;
GRANT EXECUTE ON FUNCTION pg_temp.team_check(boolean,text),pg_temp.team_reject(text,text) TO authenticated,anon,service_role;
INSERT INTO public.bookings(id,owner_id,professional_id,service_id,start_at,end_at,status)
SELECT ('e8310000-0000-0000-0005-'||lpad(n::text,12,'0'))::uuid,'e8310000-0000-0000-0000-000000000007','e8310000-0000-0000-0000-000000000006','e8310000-0000-0000-0001-000000000006',now()-interval '1 day'+starts*interval '1 minute',now()-interval '1 day'+ends*interval '1 minute','pending' FROM (VALUES(4,0,60),(5,30,90),(6,90,150)) t(n,starts,ends);
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000006',false);
SELECT public.change_booking_status(id,'accepted') FROM public.bookings WHERE id::text LIKE 'e8310000-0000-0000-0005-%' AND status='pending';
SELECT public.assign_booking_instructor('e8310000-0000-0000-0005-000000000004','e8310000-0000-0000-0006-000000000002');
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000002')$q$,'PCX01');
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000002')$q$,'PCX01');
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000002','00000000-0000-0000-0000-000000000000',true)$q$,'40001');
SELECT pg_temp.team_check(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000005']::uuid[])#>>'{0,instructor_id}' IS NULL,'Rejected overlap has no assignment');
SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000002',NULL,true);
SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000002',NULL,true);
SELECT pg_temp.team_check(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000005']::uuid[])#>>'{0,overlap_confirmed}'='true','Group lesson explicitly confirmed');
SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000006','e8310000-0000-0000-0006-000000000002',NULL,true);
SELECT pg_temp.team_check(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000006']::uuid[])#>>'{0,overlap_confirmed}'='false','Adjacent intervals do not overlap; no fabricated acknowledgement');
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000007',false);
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005',NULL,NULL,true)$q$,'42501');
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000002',false);
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000003',NULL,true)$q$,'42501');
SELECT pg_temp.team_check(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000005']::uuid[])='[]'::jsonb,'Other centre cannot see group lesson acknowledgement');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
SELECT pg_temp.team_check((SELECT count(*)=1 FROM pc_private.centre_team_history WHERE kind='assignment' AND booking_id='e8310000-0000-0000-0005-000000000005'),'Group retry creates one event');
SELECT pg_temp.team_check((SELECT new_value->>'overlap_confirmed'='true' FROM pc_private.centre_team_history WHERE kind='assignment' AND booking_id='e8310000-0000-0000-0005-000000000005'),'Confirmation kept in audit');
SET ROLE anon;
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005',NULL,NULL,true)$q$,'42501');
RESET ROLE;
SET ROLE service_role;
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005',NULL,NULL,true)$q$,'42501');
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e8310000-0000-0000-0000-000000000006',false);
SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005',NULL,(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000005']::uuid[])#>>'{0,version}')::uuid,true);
SELECT pg_temp.team_check(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000005']::uuid[])#>>'{0,overlap_confirmed}'='false','Clearing assignment clears current acknowledgement');
SELECT public.change_booking_status('e8310000-0000-0000-0005-000000000004','completed');
SELECT pg_temp.team_reject($q$SELECT public.assign_booking_instructor_checked('e8310000-0000-0000-0005-000000000005','e8310000-0000-0000-0006-000000000002',(public.get_booking_instructors(ARRAY['e8310000-0000-0000-0005-000000000005']::uuid[])#>>'{0,version}')::uuid,false)$q$,'PCX01');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
